1	//! The [`Runner`] trait and its carrier types.
2	//!
3	//! The runner is the durability seam (per ADR-6): swappable between
4	//! ephemeral tokio (`paigasus-helikon-runtime-tokio`), durable Temporal
5	//! (`paigasus-helikon-runtime-temporal`), and AWS AgentCore
6	//! (`paigasus-helikon-runtime-agentcore`).
7	
8	use std::num::NonZeroUsize;
9	use std::time::Duration;
10	
11	use async_trait::async_trait;
12	
13	use crate::{
14	    Agent, AgentError, AgentEvent, AgentInput, ContentPart, FailureSlot, Item, RunContext,
15	};
16	
17	/// Pluggable execution backend.
18	///
19	/// `Runner` is object-safe: all methods accept `&dyn Agent<Ctx>` rather
20	/// than a generic `<A: Agent<Ctx>>` parameter, which keeps the trait
21	/// vtable-friendly while remaining compatible with both concrete and
22	/// trait-object agent references.
23	///
24	/// See ADR-6 (*Library + pluggable Runner trait*).
25	///
26	/// # Example
27	///
28	/// ```
29	/// use async_trait::async_trait;
30	/// use futures_core::stream::BoxStream;
31	/// use futures_util::stream::empty;
32	/// use paigasus_helikon_core::{
33	///     Agent, AgentEvent, AgentInput, RunConfig, RunContext, RunError,
34	///     RunResult, RunResultStreaming, Runner,
35	/// };
36	///
37	/// struct NoopRunner;
38	///
39	/// #[async_trait]
40	/// impl Runner<()> for NoopRunner {
41	///     async fn run(
42	///         &self,
43	///         _agent: &(dyn Agent<()> + '_),
44	///         _ctx: RunContext<()>,
45	///         _input: AgentInput,
46	///         _config: RunConfig,
47	///     ) -> Result<RunResult, RunError> {
48	///         Ok(RunResult::default())
49	///     }
50	///
51	///     async fn run_streamed(
52	///         &self,
53	///         _agent: &(dyn Agent<()> + '_),
54	///         _ctx: RunContext<()>,
55	///         _input: AgentInput,
56	///         _config: RunConfig,
57	///     ) -> Result<RunResultStreaming, RunError> {
58	///         let stream: BoxStream<'static, AgentEvent> = Box::pin(empty());
59	///         Ok(RunResultStreaming::new(stream))
60	///     }
61	/// }
62	/// ```
63	#[async_trait]
64	pub trait Runner<Ctx>: Send + Sync
65	where
66	    Ctx: Send + Sync + 'static,
67	{
68	    /// Run the agent to completion and return the aggregated result.
69	    ///
70	    /// **With a `Session`** (always present on [`RunContext`]): the runner loads
71	    /// persisted history at start and seeds the conversation as
72	    /// `history ++ input.messages`, so `input` is the *new turn* — the session
73	    /// owns history. The run's events are persisted at exit. To continue with no
74	    /// new turn (or to retry a failed run without re-appending the user message),
75	    /// use [`Runner::resume`].
76	    ///
77	    /// **Cancellation/timeout is best-effort and loses to a genuine terminal
78	    /// event that already occurred.** If the run reaches a terminal
79	    /// (`RunCompleted`/`RunFailed`) before — or in the same poll as — a cancel or
80	    /// timeout, the runner reports that real outcome (`Ok`, or the structured
81	    /// `Err(RunError::Agent(..))`), not `Err(RunError::Cancelled)` /
82	    /// `Err(RunError::Timeout)`. The cancel/timeout wins only when it aborted the
83	    /// run in-flight, before any terminal event. A caller therefore cannot assume
84	    /// "I called `cancel()` ⇒ I get `Cancelled`".
85	    async fn run(
86	        &self,
87	        agent: &(dyn Agent<Ctx> + '_),
88	        ctx: RunContext<Ctx>,
89	        input: AgentInput,
90	        config: RunConfig,
91	    ) -> Result<RunResult, RunError>;
92	
93	    /// Run the agent and return a streaming result handle.
94	    ///
95	    /// Session loading/seeding matches [`Runner::run`]. **The returned stream
96	    /// must be driven to its terminal for the run's events to be persisted:** a
97	    /// consumer that drops the stream early may skip the finalize step and leave
98	    /// a partial turn (or nothing) written.
99	    ///
100	    /// The same cancellation precedence as [`Runner::run`] applies: once a real
101	    /// terminal event has been yielded, a late cancel/timeout does not append a
102	    /// second, synthetic terminal — the stream ends after the real one.
103	    async fn run_streamed(
104	        &self,
105	        agent: &(dyn Agent<Ctx> + '_),
106	        ctx: RunContext<Ctx>,
107	        input: AgentInput,
108	        config: RunConfig,
109	    ) -> Result<RunResultStreaming, RunError>;
110	
111	    /// Resume a run from the session's persisted history with no new input.
112	    ///
113	    /// Equivalent to [`Runner::run`] with an empty [`AgentInput`]: the runner
114	    /// loads the conversation from `ctx.session()` and continues it. Use this to
115	    /// continue a multi-turn session, or to retry a failed run without
116	    /// re-appending the previous turn's user message. (With a `Session` present,
117	    /// [`Runner::run`]'s `input` is the *new turn*; the session owns history.)
118	    async fn resume(
119	        &self,
120	        agent: &(dyn Agent<Ctx> + '_),
121	        ctx: RunContext<Ctx>,
122	        config: RunConfig,
123	    ) -> Result<RunResult, RunError> {
124	        self.run(agent, ctx, AgentInput::new(), config).await
125	    }
126	
127	    /// Streaming counterpart of [`Runner::resume`]: resumes from session
128	    /// history with no new input and returns a streaming result handle instead
129	    /// of an aggregated [`RunResult`].
130	    async fn resume_streamed(
131	        &self,
132	        agent: &(dyn Agent<Ctx> + '_),
133	        ctx: RunContext<Ctx>,
134	        config: RunConfig,
135	    ) -> Result<RunResultStreaming, RunError> {
136	        self.run_streamed(agent, ctx, AgentInput::new(), config)
137	            .await
138	    }
139	}
140	
141	/// Per-run configuration.
142	///
143	/// SMA-314 shipped `max_turns`; SMA-321 added `timeout` and
144	/// `parallel_tool_call_limit`. Cancellation is intentionally *not* a field
145	/// here — the canonical token lives on [`crate::RunContext`].
146	#[derive(Debug, Clone)]
147	#[non_exhaustive]
148	pub struct RunConfig {
149	    /// `[driver-scoped]` Maximum number of model turns before the loop fails
150	    /// with [`crate::AgentError::MaxTurnsExceeded`]. Honored by the core loop
151	    /// driver, including on a bare `agent.run()` with no runner. Default `16`.
152	    pub max_turns: u32,
153	    /// `[runner-scoped]` Wall-clock deadline for the whole run. Honored ONLY by
154	    /// a runtime backend (e.g. `TokioRunner`); a bare `agent.run()` cannot time
155	    /// out (core has no timer). `None` = no deadline.
156	    pub timeout: Option<Duration>,
157	    /// `[driver-scoped]` Cap on concurrently-executing tool calls. Honored by
158	    /// the core loop driver. `None` = unbounded (today's behavior).
159	    pub parallel_tool_call_limit: Option<NonZeroUsize>,
160	    /// `[driver-scoped]` Maximum agent-nesting depth across **both** handoff
161	    /// chains and `AgentAsTool` sub-runs. Each nested agent run increments the
162	    /// depth; exceeding this fails with
163	    /// [`crate::AgentError::MaxAgentDepthExceeded`]. Default `8`.
164	    pub max_agent_depth: u32,
165	}
166	
167	impl Default for RunConfig {
168	    fn default() -> Self {
169	        Self {
170	            max_turns: 16,
171	            timeout: None,
172	            parallel_tool_call_limit: None,
173	            max_agent_depth: 8,
174	        }
175	    }
176	}
177	
178	impl RunConfig {
179	    /// Construct a default config (`max_turns = 16`).
180	    pub fn new() -> Self {
181	        Self::default()
182	    }
183	
184	    /// Set the wall-clock run deadline. Honored by a runtime backend (e.g. `TokioRunner`).
185	    pub fn with_timeout(mut self, timeout: Duration) -> Self {
186	        self.timeout = Some(timeout);
187	        self
188	    }
189	
190	    /// Cap the number of tool calls executed concurrently. Honored by the core loop driver.
191	    pub fn with_parallel_tool_call_limit(mut self, limit: NonZeroUsize) -> Self {
192	        self.parallel_tool_call_limit = Some(limit);
193	        self
194	    }
195	
196	    /// Set the maximum agent-nesting depth (handoff + agent-as-tool). Honored by the core loop driver.
197	    pub fn with_max_agent_depth(mut self, depth: u32) -> Self {
198	        self.max_agent_depth = depth;
199	        self
200	    }
201	}
