203	/// The aggregated outcome of a non-streaming [`Runner::run`].
204	///
205	/// Generic over the structured-output type. The default `T = String`
206	/// makes the common case ergonomic; structured-output callers build
207	/// `RunResult<MyStruct>` via [`RunResult::parse_final`].
208	#[derive(Debug, Default, Clone)]
209	#[non_exhaustive]
210	pub struct RunResult<T = String> {
211	    /// The model's final assistant output, deserialized into `T`. For
212	    /// the default `T = String` this is the literal text.
213	    pub final_output: T,
214	    /// Every [`AgentEvent`] emitted during the run, in order.
215	    pub events: Vec<AgentEvent>,
216	    /// Aggregated token usage across every turn of the run.
217	    pub usage: TokenUsage,
218	}
219	
220	impl RunResult<String> {
221	    /// Deserialize `final_output` into `T`, producing a typed
222	    /// [`RunResult`].
223	    ///
224	    /// The `T: JsonSchema` bound is the marker that the caller has
225	    /// configured structured output upstream — without it,
226	    /// `parse_final` is just a JSON parse over unstructured text.
227	    pub fn parse_final<T>(self) -> Result<RunResult<T>, serde_json::Error>
228	    where
229	        T: serde::de::DeserializeOwned + schemars::JsonSchema,
230	    {
231	        let final_output = serde_json::from_str::<T>(&self.final_output)?;
232	        Ok(RunResult {
233	            final_output,
234	            events: self.events,
235	            usage: self.usage,
236	        })
237	    }
238	}
239	
240	/// Streaming counterpart of [`RunResult`].
241	///
242	/// Wraps the unified [`crate::AgentEvent`] stream emitted by an agent
243	/// and offers an `async fn collect` that drains the stream into a
244	/// `RunResult<String>`. Callers may consume `events` directly for raw
245	/// streaming.
246	pub struct RunResultStreaming {
247	    /// The event stream produced by the agent's run.
248	    pub events: futures_core::stream::BoxStream<'static, crate::AgentEvent>,
249	    /// Side-channel carrying the run's terminal structured [`AgentError`], when
250	    /// a runner wired one in via [`RunResultStreaming::with_failure`]. Read only
251	    /// after the stream is fully drained. `None` for a bare
252	    /// [`RunResultStreaming::new`], in which case `collect` falls back to the
253	    /// string error from [`AgentEvent::RunFailed`].
254	    failure: Option<FailureSlot>,
255	}
256	
257	impl RunResultStreaming {
258	    /// Wrap an event stream with no structured-error side-channel. `collect`
259	    /// then surfaces failures as the opaque string from `RunFailed`.
260	    pub fn new(events: futures_core::stream::BoxStream<'static, crate::AgentEvent>) -> Self {
261	        Self {
262	            events,
263	            failure: None,
264	        }
265	    }
266	
267	    /// Wrap an event stream together with the [`FailureSlot`] the agent records
268	    /// its terminal structured [`AgentError`] into, so `collect` /
269	    /// `collect_typed` surface `RunError::Agent` / the real `AgentError` instead
270	    /// of the opaque string.
271	    pub fn with_failure(
272	        events: futures_core::stream::BoxStream<'static, crate::AgentEvent>,
273	        failure: FailureSlot,
274	    ) -> Self {
275	        Self {
276	            events,
277	            failure: Some(failure),
278	        }
279	    }
280	
281	    /// Drain the stream and aggregate into a `RunResult<String>`.
282	    ///
283	    /// `final_output` is the concatenated text from the *last*
284	    /// `AgentEvent::MessageOutput { item: AssistantMessage }`. In multi-turn
285	    /// flows, each new assistant message resets `final_output`, ensuring
286	    /// the result is the terminal assistant output, not intermediate text.
287	    /// Structured-output callers go through `RunResult::<String>::parse_final::<T>()`
288	    /// (SMA-313).
289	    pub async fn collect(mut self) -> Result<RunResult, RunError> {
290	        use futures_util::stream::StreamExt;
291	        let mut events = Vec::new();
292	        let mut final_output = String::new();
293	        let mut usage = crate::TokenUsage::default();
294	        // Capture the RunFailed string but keep draining: state-machine failures
295	        // record their structured error AFTER yielding RunFailed, so the slot is
296	        // only guaranteed populated once the stream ends.
297	        let mut failed: Option<String> = None;
298	
299	        while let Some(ev) = self.events.next().await {
300	            match &ev {
301	                crate::AgentEvent::MessageOutput {
302	                    item: crate::Item::AssistantMessage { content, .. },
303	                } => {
304	                    final_output.clear();
305	                    for part in content {
306	                        if let crate::ContentPart::Text { text } = part {
307	                            final_output.push_str(text);
308	                        }
309	                    }
310	                }
311	                crate::AgentEvent::RunCompleted { usage: u } => usage = *u,
312	                crate::AgentEvent::RunFailed { error } => {
313	                    failed = Some(error.clone());
314	                }
315	                _ => {}
316	            }
317	            events.push(ev);
318	        }
319	
320	        if let Some(err_msg) = failed {
321	            if let Some(err) = self.failure.as_ref().and_then(FailureSlot::take) {
322	                return Err(RunError::Agent(err));
323	            }
324	            return Err(RunError::Other(anyhow::anyhow!(err_msg)));
325	        }
326	
327	        Ok(RunResult {
328	            final_output,
329	            events,
330	            usage,
331	        })
332	    }
333	
334	    /// Drain the stream and deserialize the terminal assistant text into `T`.
335	    ///
336	    /// The terminal output is the concatenated text of the last
337	    /// [`AgentEvent::MessageOutput`]. On a correctly configured structured run
338	    /// the agent loop has already validated that text against `T`, so the parse
339	    /// here is expected to succeed; if it fails (e.g. `collect_typed` is called
340	    /// on a plain-text run), the parse error surfaces as [`AgentError::Other`].
341	    /// A failed run surfaces the underlying [`AgentError`]:
342	    /// structured-validation failures (carried by
343	    /// [`AgentEvent::StructuredOutputFailed`]) become
344	    /// [`AgentError::InvalidStructuredOutput`]; any other terminal
345	    /// [`AgentEvent::RunFailed`] becomes [`AgentError::Other`].
346	    pub async fn collect_typed<T>(mut self) -> Result<RunResult<T>, AgentError>
347	    where
348	        T: serde::de::DeserializeOwned,
349	    {
350	        use futures_util::stream::StreamExt;
351	        let mut events = Vec::new();
352	        let mut final_text = String::new();
353	        let mut usage = crate::TokenUsage::default();
354	        let mut structured_err: Option<(Vec<String>, String)> = None;
355	        let mut failed: Option<String> = None;
356	
357	        while let Some(ev) = self.events.next().await {
358	            match &ev {
359	                AgentEvent::MessageOutput {
360	                    item: Item::AssistantMessage { content, .. },
361	                } => {
362	                    final_text.clear();
363	                    for part in content {
364	                        if let ContentPart::Text { text } = part {
365	                            final_text.push_str(text);
366	                        }
367	                    }
368	                }
369	                AgentEvent::RunCompleted { usage: u } => usage = *u,
370	                AgentEvent::StructuredOutputFailed {
371	                    schema_errors,
372	                    final_text: ft,
373	                } => {
374	                    structured_err = Some((schema_errors.clone(), ft.clone()));
375	                }
376	                AgentEvent::RunFailed { error } => {
377	                    failed = Some(error.clone());
378	                }
379	                _ => {}
380	            }
381	            events.push(ev);
382	        }
383	
384	        if let Some(err_msg) = failed {
385	            // Primary: the structured side-channel (populated post-drain).
386	            if let Some(err) = self.failure.as_ref().and_then(FailureSlot::take) {
387	                return Err(err);
388	            }
389	            // Fallback 1: reconstruct InvalidStructuredOutput from its event.
390	            if let Some((schema_errors, final_text)) = structured_err {
391	                return Err(AgentError::InvalidStructuredOutput {
392	                    schema_errors,
393	                    final_text,
394	                });
395	            }
396	            // Fallback 2: the opaque string.
397	            return Err(AgentError::Other(anyhow::anyhow!(err_msg)));
398	        }
399	
400	        let final_output = serde_json::from_str::<T>(final_text.trim()).map_err(|e| {
401	            AgentError::Other(anyhow::anyhow!(
402	                "collect_typed: failed to deserialize final output: {e}"
403	            ))
404	        })?;
405	        Ok(RunResult {
406	            final_output,
407	            events,
408	            usage,
409	        })
410	    }
411	}
