413	/// Token usage aggregated across all turns of a run.
414	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
415	#[non_exhaustive]
416	pub struct TokenUsage {
417	    /// Prompt tokens billed for this run.
418	    pub input_tokens: u64,
419	    /// Completion tokens billed for this run.
420	    pub output_tokens: u64,
421	    /// Tokens served from prompt cache (OpenAI prompt-caching, Anthropic
422	    /// prompt-caching). Counted as `input_tokens` by the provider; this
423	    /// field is informational.
424	    pub cached_input_tokens: u64,
425	    /// Reasoning tokens billed (OpenAI o-series, Anthropic extended
426	    /// thinking).
427	    pub reasoning_tokens: u64,
428	    /// Provider-reported total. May differ from
429	    /// `input_tokens + output_tokens` when the provider excludes cached or
430	    /// reasoning tokens from the billed total. Preserve the provider's
431	    /// value; do not recompute it.
432	    pub total_tokens: u64,
433	}
434	
435	impl TokenUsage {
436	    /// Add another usage record (per-turn aggregation across a run).
437	    ///
438	    /// `total_tokens` is summed alongside the other fields rather than
439	    /// recomputed from them, preserving each turn's provider-reported total.
440	    pub fn add(&mut self, other: TokenUsage) {
441	        self.input_tokens += other.input_tokens;
442	        self.output_tokens += other.output_tokens;
443	        self.cached_input_tokens += other.cached_input_tokens;
444	        self.reasoning_tokens += other.reasoning_tokens;
445	        self.total_tokens += other.total_tokens;
446	    }
447	}
