449	/// Errors raised by [`Runner`] methods.
450	#[derive(Debug, thiserror::Error)]
451	#[non_exhaustive]
452	pub enum RunError {
453	    /// The underlying agent failed.
454	    #[error("agent failed: {0}")]
455	    Agent(#[from] AgentError),
456	
457	    /// The runner hit the configured maximum iteration count.
458	    #[error("max iterations reached")]
459	    MaxIterations,
460	
461	    /// The run was cancelled (e.g. via [`crate::CancellationToken`]).
462	    #[error("cancelled")]
463	    Cancelled,
464	
465	    /// The run exceeded its configured [`RunConfig::timeout`].
466	    #[error("run timed out")]
467	    Timeout,
468	
469	    /// Escape hatch.
470	    #[error(transparent)]
471	    Other(#[from] anyhow::Error),
472	}
