1	//! `paigasus-helikon-runtime-tokio` — the default ephemeral Tokio runner.
2	//!
3	//! [`TokioRunner`] implements [`paigasus_helikon_core::Runner`] by consuming
4	//! the agent's [`paigasus_helikon_core::AgentEvent`] stream and adding
5	//! run-level control (cancellation, timeout, aggregation) at the boundary. It
6	//! does not own the loop driver — the agent does (see ADR-13).
7	
8	use std::sync::{Arc, Mutex};
9	use std::time::Duration;
10	
11	use async_trait::async_trait;
12	use futures_core::stream::BoxStream;
