45	/// Wrap an agent event stream with cancel/deadline control.
46	///
47	/// Passes agent events through. On cancellation or deadline it commits the
48	/// reason into the returned handle and ends the stream (dropping the inner
49	/// stream cancels nested in-flight awaits within one poll). The outcome is
50	/// committed *before* the terminating `None`, so a caller reading the handle
51	/// after draining never sees a stale value.
52	fn controlled(
53	    mut stream: BoxStream<'static, AgentEvent>,
54	    cancel: CancellationToken,
55	    timeout: Option<Duration>,
56	) -> (BoxStream<'static, AgentEvent>, OutcomeHandle) {
57	    let cell = Arc::new(Mutex::new(Outcome::Completed));
58	    let handle = OutcomeHandle(Arc::clone(&cell));
59	    let out = async_stream::stream! {
60	        let sleep = async move {
61	            match timeout {
62	                Some(d) => tokio::time::sleep(d).await,
63	                None => std::future::pending::<()>().await,
64	            }
65	        };
66	        tokio::pin!(sleep);
67	        loop {
68	            tokio::select! {
69	                biased;
70	                maybe_ev = stream.next() => {
71	                    match maybe_ev {
72	                        Some(ev) => yield ev,
73	                        None => break, // inner stream done => Completed (default)
74	                    }
75	                }
76	                () = cancel.cancelled() => {
77	                    *cell.lock().unwrap() = Outcome::Cancelled;
78	                    break;
79	                }
80	                () = &mut sleep => {
81	                    *cell.lock().unwrap() = Outcome::TimedOut;
82	                    break;
83	                }
84	            }
85	        }
86	    };
87	    (Box::pin(out), handle)
88	}
