90	/// Snapshot the session into the merged input and seed a recorder with the
91	/// run's new-turn messages. A read failure is a hard error: the run cannot
92	/// faithfully resume from an unreadable session, so it fails before the agent
93	/// starts. (The write side, by contrast, is best-effort — see `finalize`.)
94	async fn load_and_record(
95	    session: &Arc<dyn Session>,
96	    agent_name: &str,
97	    input: AgentInput,
98	) -> Result<(AgentInput, Arc<Mutex<SessionRecorder>>), RunError> {
99	    let snapshot = session
100	        .snapshot()
101	        .await
102	        .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
103	    let mut recorder = SessionRecorder::new(agent_name);
104	    recorder.record_input(&input.messages);
105	
106	    let mut merged = AgentInput::new();
107	    merged.messages = snapshot.messages;
108	    merged.messages.extend(input.messages);
109	    Ok((merged, Arc::new(Mutex::new(recorder))))
110	}
