112	/// Post-run finalization: drain the recorder and append the run's events.
113	/// Persistence is best-effort — an append error is logged, never propagated, so
114	/// the run's outcome (Ok / Cancelled / Timeout / Agent error) is unchanged.
115	async fn finalize(session: &Arc<dyn Session>, recorder: &Arc<Mutex<SessionRecorder>>) {
116	    let events = recorder
117	        .lock()
118	        .expect("session recorder mutex poisoned")
119	        .drain();
120	    if let Err(e) = session.append(&events).await {
121	        tracing::warn!(
122	            error = %e,
123	            "session persistence failed during finalize; run outcome unaffected"
124	        );
125	    }
126	}
